import { getAppId } from "../../utils/getAppId.js";
import { isNewPathEnabled } from "../../utils/apiPath.js";
const DEFAULT_CONFIG = {
    getAppId: ()=>getAppId(),
    searchDepartmentUrl: (appId)=>isNewPathEnabled() ? `/app/${appId}/__runtime__/api/v1/account/search_department` : `/af/app/${appId}/runtime/api/v1/account/search_department`
};
class DepartmentService {
    config;
    constructor(config = {}){
        this.config = {
            ...DEFAULT_CONFIG,
            ...config
        };
    }
    async searchDepartments(params) {
        const appId = this.config.getAppId();
        if (!appId) throw new Error('Failed to get appId');
        const response = await fetch(this.config.searchDepartmentUrl(appId), {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(params),
            credentials: 'include'
        });
        if (!response.ok) throw new Error('Failed to search departments');
        return response.json();
    }
}
export { DepartmentService };
